namespace UniversityCourseCatalog.Models;

public class Course
{
    public int Id { get; set; }
    public string Code { get; set; } = string.Empty;
    public string Title { get; set; } = string.Empty;
    public string Description { get; set; } = string.Empty;
    public int Credits { get; set; }
    public string Schedule { get; set; } = string.Empty;
    public string InstructorName { get; set; } = string.Empty;
    public string InstructorBio { get; set; } = string.Empty;
    public string DepartmentCode { get; set; } = string.Empty;
    public bool IsFeatured { get; set; }
}

public class Department
{
    public string Code { get; set; } = string.Empty;
    public string Name { get; set; } = string.Empty;
}

public class EnrollmentRequest
{
    public string StudentName { get; set; } = string.Empty;
    public string StudentId { get; set; } = string.Empty;
    public int CourseId { get; set; }
}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private static readonly List<Department> Departments =
    [
        new() { Code = "CS", Name = "Computer Science" },
        new() { Code = "MATH", Name = "Mathematics" },
        new() { Code = "ENG", Name = "English" },
        new() { Code = "PHYS", Name = "Physics" },
        new() { Code = "HIST", Name = "History" }
    ];

    private static readonly List<Course> Courses =
    [
        new()
        {
            Id = 1, Code = "CS 101", Title = "Introduction to Programming",
            Description = "Learn the fundamentals of programming using C#. Covers variables, control flow, functions, and object-oriented basics.",
            Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", DepartmentCode = "CS",
            InstructorName = "Dr. Ada Lovelace", InstructorBio = "Professor of Computer Science with 15 years of teaching experience specializing in programming languages and software engineering.",
            IsFeatured = true
        },
        new()
        {
            Id = 2, Code = "CS 201", Title = "Data Structures and Algorithms",
            Description = "Study of fundamental data structures (arrays, linked lists, trees, graphs) and algorithm design techniques (sorting, searching, dynamic programming).",
            Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", DepartmentCode = "CS",
            InstructorName = "Dr. Alan Turing", InstructorBio = "Award-winning researcher in computational theory and algorithm optimization with numerous published papers.",
            IsFeatured = true
        },
        new()
        {
            Id = 3, Code = "CS 301", Title = "Database Systems",
            Description = "Relational database design, SQL, normalization, transaction processing, and introduction to NoSQL databases.",
            Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", DepartmentCode = "CS",
            InstructorName = "Dr. Edgar Codd", InstructorBio = "Database architect with industry experience at major tech companies before transitioning to academia.",
            IsFeatured = false
        },
        new()
        {
            Id = 4, Code = "MATH 101", Title = "Calculus I",
            Description = "Limits, derivatives, and integrals of single-variable functions. Applications to physics and engineering.",
            Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", DepartmentCode = "MATH",
            InstructorName = "Dr. Isaac Newton", InstructorBio = "Mathematics professor passionate about connecting abstract calculus concepts to real-world applications.",
            IsFeatured = true
        },
        new()
        {
            Id = 5, Code = "MATH 201", Title = "Linear Algebra",
            Description = "Vectors, matrices, linear transformations, eigenvalues, and applications in data science and computer graphics.",
            Credits = 3, Schedule = "Tue/Thu 1:00–2:15 PM", DepartmentCode = "MATH",
            InstructorName = "Dr. Emmy Noether", InstructorBio = "Specialist in abstract algebra with a gift for making complex mathematical concepts accessible to undergraduates.",
            IsFeatured = false
        },
        new()
        {
            Id = 6, Code = "ENG 101", Title = "Composition and Rhetoric",
            Description = "Develop effective writing skills through essays, research papers, and critical analysis of texts.",
            Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", DepartmentCode = "ENG",
            InstructorName = "Dr. Virginia Woolf", InstructorBio = "Published author and writing instructor dedicated to helping students find their unique voice.",
            IsFeatured = false
        },
        new()
        {
            Id = 7, Code = "ENG 220", Title = "American Literature",
            Description = "Survey of American literary works from the colonial period to the present, exploring themes of identity, freedom, and social change.",
            Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", DepartmentCode = "ENG",
            InstructorName = "Dr. Mark Twain", InstructorBio = "Literary scholar with expertise in 19th and 20th century American fiction and cultural criticism.",
            IsFeatured = true
        },
        new()
        {
            Id = 8, Code = "PHYS 101", Title = "General Physics I",
            Description = "Mechanics, thermodynamics, and waves. Includes weekly laboratory sessions with hands-on experiments.",
            Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Lab Thu 2:00–4:00 PM", DepartmentCode = "PHYS",
            InstructorName = "Dr. Marie Curie", InstructorBio = "Experimental physicist with active research in materials science who brings cutting-edge discoveries into the classroom.",
            IsFeatured = false
        },
        new()
        {
            Id = 9, Code = "PHYS 201", Title = "Electromagnetism",
            Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.",
            Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM + Lab Fri 2:00–4:00 PM", DepartmentCode = "PHYS",
            InstructorName = "Dr. James Maxwell", InstructorBio = "Theoretical physicist specializing in electromagnetic theory with a talent for visual demonstrations.",
            IsFeatured = false
        },
        new()
        {
            Id = 10, Code = "HIST 101", Title = "World Civilizations",
            Description = "A global survey of major civilizations from ancient Mesopotamia through the early modern period.",
            Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", DepartmentCode = "HIST",
            InstructorName = "Dr. Herodotus Smith", InstructorBio = "Historian with field research experience across three continents and a focus on cross-cultural exchange.",
            IsFeatured = false
        },
        new()
        {
            Id = 11, Code = "HIST 250", Title = "Modern European History",
            Description = "Europe from the French Revolution to the present, covering political revolutions, industrialization, world wars, and European integration.",
            Credits = 3, Schedule = "Tue/Thu 3:00–4:15 PM", DepartmentCode = "HIST",
            InstructorName = "Dr. Elizabeth Ashton", InstructorBio = "European history specialist who integrates primary sources and digital archives into an engaging curriculum.",
            IsFeatured = true
        }
    ];

    public List<Department> GetDepartments() => Departments;

    public Department? GetDepartment(string code) =>
        Departments.FirstOrDefault(d => d.Code.Equals(code, StringComparison.OrdinalIgnoreCase));

    public List<Course> GetCourses(string? department = null, string? search = null)
    {
        var query = Courses.AsEnumerable();

        if (!string.IsNullOrWhiteSpace(department))
            query = query.Where(c => c.DepartmentCode.Equals(department, StringComparison.OrdinalIgnoreCase));

        if (!string.IsNullOrWhiteSpace(search))
            query = query.Where(c =>
                c.Title.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(search, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(search, StringComparison.OrdinalIgnoreCase));

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() =>
        Courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) =>
        Courses.FirstOrDefault(c => c.Id == id);

    public bool SubmitEnrollmentRequest(EnrollmentRequest request) =>
        !string.IsNullOrWhiteSpace(request.StudentName) &&
        !string.IsNullOrWhiteSpace(request.StudentId) &&
        request.CourseId > 0 &&
        Courses.Any(c => c.Id == request.CourseId);
}

